head.script:
scwin.fn_slideHide = function(e) {
    if (slideHide1.getUserData("edu_flag") == null) {
        slideHide1.setUserData("edu_flag", "y");
        slideHide1.startHide();
    } else {
        slideHide1.setUserData("edu_flag", null);
        slideHide1.startSlide();
    }
};
scwin.__isCloseToRight = function() {
    //debugger;
    if (slideLeft == "auto") {
        return parseInt(WebSquare.wUnit.getJq("#slideHide1").css("left")) > 0;
    }
    return parseInt(WebSquare.wUnit.getJq("#slideHide1").css("left")) > parseInt(slideLeft);
}
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    // Test step 2. 브라우저에서 slide/hide 버튼을 클릭한다.
    //2. In your browser, click the slide / hide button.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wq_uuid_1').click()");
    WebSquare.wUnit.addCommand("pause", "1000");
    // verify step 2. 왼쪽에서 오른쪽으로 닫힌다. (그전버전에서는 IE 와 Edge 브라우저에서 오른쪽 -> 왼쪽으로 이동되는 현상발생)
    //2. Close from left to right. (In previous versions, IE and Edge browser moved from right to left)
    WebSquare.wUnit.addCommand("assert", "scwin.__isCloseToRight()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function unitTest
    //Created By: Sang.do
    //Created By: 13-Feb-2018
    window.slideLeft = WebSquare.wUnit.getJq("#slideHide1").css("left");
    //end unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
